import itertools

def get_C(N, s, w):
    C = [[0]*N for _ in range(N)]
    # w is a tuple of weights for each possible tile position (x, y)
    # tile positions are x in 0..N-s, y in 0..N-s
    idx = 0
    for x in range(N-s+1):
        for y in range(N-s+1):
            weight = w[idx]
            for i in range(x, x+s):
                for j in range(y, y+s):
                    C[i][j] += weight
            idx += 1
    return C

def solve_small(N, s):
    max_k = 0
    # Weights can be anything, but for small N, s, we can try small integers
    # Actually, we can try weights in {0, 1, 2}
    for w in itertools.product([0, 1, 2], repeat=(N-s+1)**2):
        C = get_C(N, s, w)
        counts = {}
        for i in range(N):
            for j in range(N):
                val = C[i][j]
                if val > 0:
                    counts[val] = counts.get(val, 0) + 1
        if counts:
            current_max = max(counts.values())
            if current_max > max_k:
                max_k = current_max
    return max_k

