def solve_small_N(N, s):
    max_k = 0
    # We can't use all weights, let's try a smaller set of weights
    # and focus on w_{x,y} = v * I(condition)
    # Since the number of tiles is small, we can try a few configurations.
    # Instead, let's try the w_{x,y} = v * I(x+y is even)
    # and w_{x,y} = v * I(x is even) and w_{x,y} = v * I(y is even)
    # and product weights.

    # Actually, let's just try random weights.
    import random
    for _ in range(1000):
        w = [random.randint(0, 1) for _ in range((N-s+1)**2)]
        C = get_C(N, s, w)
        counts = {}
        for i in range(N):
            for j in range(N):
                val = C[i][j]
                if val > 0:
                    counts[val] = counts.get(val, 0) + 1
        if counts:
            max_k = max(max_k, max(counts.values()))
    return max_k

