def solve_all_tiles(N, s):
    # C(i, j) = |X_i \cap X_j|
    # X_i = [max(0, i-s+1), min(N-s, i)]
    counts = {}
    for i in range(N):
        left_i = max(0, i-s+1)
        right_i = min(N-s, i)
        for j in range(i, N):
            left_j = max(0, j-s+1)
            right_j = min(N-s, j)

            # Intersection of [left_i, right_i] and [left_j, right_j]
            inter_left = max(left_i, left_j)
            inter_right = min(right_i, right_j)
            val = max(0, inter_right - inter_left + 1)

            if val > 0:
                # i, j is one cell. If i == j, it's one cell, else it's two.
                num_cells = 1 if i == j else 2
                counts[val] = counts.get(val, 0) + num_cells

    if counts:
        return max(counts.values())
    return 0

